#!/usr/bin/env python3
from pathlib import Path
import shutil

tsx=Path("frontend/src/midpointStrategyShadow.tsx")
css=Path("frontend/src/midpointStrategyShadow.css")
for p in (tsx,css):
    if not p.exists():
        raise SystemExit(f"STOP: missing {p}")
    b=p.with_name(p.name+".pre-m2-5a.bak")
    if not b.exists():
        shutil.copy2(p,b)
        print("BACKUP:",b)

text=tsx.read_text()
helper='\nfunction ageLabel(ts:string|null|undefined){\n if(!ts)return\'—\'\n const ms=Date.now()-Date.parse(ts)\n if(!Number.isFinite(ms))return\'—\'\n const s=Math.max(0,Math.floor(ms/1000))\n if(s<60)return`${s}s`\n const m=Math.floor(s/60)\n if(m<60)return`${m}m ${s%60}s`\n const h=Math.floor(m/60)\n return`${h}h ${m%60}m`\n}\n\nfunction sourceLabel(mode:\'LIVE\'|\'HISTORICAL_REPLAY\',source?:string|null){\n if(mode===\'LIVE\')return\'LIVE SHADOW\'\n if(source===\'FORWARD_OOS_REPLAY\')return\'FORWARD OOS REPLAY · NO-REENTRY\'\n if(source===\'V57_PARITY_PROVEN_REPLAY\')return\'V57 PARITY-PROVEN REPLAY\'\n return words(source)\n}\n\nfunction MidpointFreshnessHeader({\n mode,status,selectedDate,selectedSession,minutes,lastRefresh\n}:{\n mode:\'LIVE\'|\'HISTORICAL_REPLAY\';\n status:Status|null;\n selectedDate:string;\n selectedSession?:Session;\n minutes:ReplayMinute[];\n lastRefresh:string|null;\n}){\n const latestAudit=status?.latest_event?.event_timestamp??null\n const latestMarket=mode===\'HISTORICAL_REPLAY\'\n   ?(minutes.at(-1)?.timestamp??null)\n   :(status?.latest_event?.event_timestamp??null)\n const sessionDate=mode===\'HISTORICAL_REPLAY\'\n   ?selectedDate\n   :(status?.latest_event?.session_date??status?.session_dates?.at(-1)??\'—\')\n const stale=mode===\'LIVE\'&&latestMarket?Date.now()-Date.parse(latestMarket)>120000:false\n\n return <section className={`mp-freshness ${stale?\'stale\':\'\'}`}>\n   <div className="mp-freshness-title">\n     <div>\n       <span>LATEST MIDPOINT DETAILS</span>\n       <b>{sessionDate}</b>\n     </div>\n     <strong>{sourceLabel(mode,selectedSession?.source)}</strong>\n   </div>\n   <div className="mp-freshness-grid">\n     <article><span>Session / trading date</span><b>{sessionDate}</b></article>\n     <article><span>Latest market/evidence time</span><b>{dt(latestMarket)}</b><small>{mode===\'LIVE\'?`age ${ageLabel(latestMarket)}`:\'replay session end\'}</small></article>\n     <article><span>Latest strategy audit</span><b>{dt(latestAudit)}</b><small>{words(status?.latest_event?.event_type)}</small></article>\n     <article><span>UI refreshed</span><b>{dt(lastRefresh)}</b><small>{mode===\'LIVE\'?\'5-second polling\':\'manual / replay load\'}</small></article>\n     <article><span>Current owner</span><b>{semanticOwner(status?.latest_event??status?.latest_entry)}</b><small>{words(status?.latest_event?.direction)}</small></article>\n     <article><span>Safety</span><b>{status?.safety.observation_only?\'OBSERVATION ONLY\':\'CHECK\'}</b><small>Execution {status?.safety.execution_enabled?\'ON\':\'OFF\'} · Paper {status?.safety.paper_order_enabled?\'ON\':\'OFF\'}</small></article>\n   </div>\n   {stale&&<div className="mp-stale-warning">Latest live evidence is older than 2 minutes. Treat the screen as stale until new evidence arrives.</div>}\n </section>\n}\n\nfunction CheckpointComparison({status}:{status:Status|null}){\n const rows=[\n   [\'ENTRY\',status?.latest_entry],\n   [\'+20 PROOF\',status?.latest_plus20],\n   [\'CLASSIFIER\',status?.latest_classifier],\n   [\'DEGRADED\',status?.latest_degraded],\n   [\'RECOVERY\',status?.latest_recovery],\n   [\'CAP20\',status?.latest_rescue],\n   [\'TERMINAL\',status?.latest_terminal],\n ] as [string,AuditEvent|null|undefined][]\n const useful=rows.filter(([,e])=>!!e)\n if(!useful.length)return null\n return <section className="panel shadow-panel mp-checkpoint-panel">\n   <div className="panel-heading"><div><h2>Lifecycle checkpoint comparison</h2><p>Compare the same trade at important state transitions without changing immutable audit evidence.</p></div><span className="pill teal">FORENSICS</span></div>\n   <div className="shadow-table-scroll"><table className="shadow-table mp-checkpoint-table">\n     <thead><tr><th>Checkpoint</th><th>Time</th><th>Owner</th><th>Direction</th><th>NIFTY</th><th>Dir pts</th><th>Fut close</th><th>Fut VWAP</th><th>Raw diff</th><th>Result / reason</th></tr></thead>\n     <tbody>{useful.map(([label,e])=>{\n       const raw=e?.futures_price!=null&&e?.futures_vwap!=null?e.futures_price-e.futures_vwap:null\n       return <tr key={label}><td><b>{label}</b></td><td>{tm(e?.event_timestamp)}</td><td>{semanticOwner(e)}</td><td>{words(e?.direction)}</td><td>{num(e?.underlying_price)}</td><td>{num(e?.directional_points)}</td><td>{num(e?.futures_price)}</td><td>{num(e?.futures_vwap)}</td><td>{raw==null?\'—\':`${raw>=0?\'+\':\'\'}${num(raw)}`}</td><td>{words(e?.result||e?.reason)}</td></tr>\n     })}</tbody>\n   </table></div>\n </section>\n}\n\nfunction nextTransitionText(m:ReplayMinute){\n const p=m.presentation\n if(!p){\n   if(m.events?.length)return\'No active B/E position at this minute. Inspect the immutable event below to see why the strategy changed state or why ownership was assigned.\'\n   return\'No active Midpoint position and no immutable strategy event at this minute.\'\n }\n if(!p.plus20)return\'Next management milestone: +20 proof — first favorable intrabar excursion of at least 20 underlying points.\'\n if(!p.classifier)return\'Next management milestone: exact +10-minute runner classifier after +20 proof. It checks positive directional progress and positive directional futures-VWAP change.\'\n if(!p.degraded)return\'Runner has been classified. Continue monitoring for joint deterioration: drawdown from running favorable excursion together with negative directional futures-VWAP change.\'\n if(p.degraded&&!p.recovered)return\'DEGRADED is active. Waiting for strict recovery through the degraded target before CAP20 rebreak timing can begin.\'\n if(p.recovered)return\'Recovery has occurred. After at least 10 minutes, the first strict rebreak of the degraded target is the CAP20 decision point; rescue is eligible only when directional move is <= +20.\'\n return\'Continue following the immutable lifecycle events.\'\n}\n\nfunction MinuteExplainPanel({m}:{m:ReplayMinute}){\n const raw=m.futures_close!=null&&m.futures_vwap!=null?m.futures_close-m.futures_vwap:null\n const p=m.presentation\n return <div className="mp-minute-explain">\n   <div className="mp-minute-explain-head"><div><span>EXPLAIN THIS MINUTE</span><b>{dt(m.timestamp)}</b></div><strong>{p?.label??(m.events?.length?words(m.events[0].event_type):\'NO ACTIVE EVENT\')}</strong></div>\n   <div className="mp-minute-explain-grid">\n     <article><span>NIFTY candle</span><b>{num(m.underlying_close)}</b><small>O {num(m.underlying_open)} · H {num(m.underlying_high)} · L {num(m.underlying_low)}</small></article>\n     <article><span>Futures vs VWAP</span><b>{raw==null?\'—\':`${raw>=0?\'+\':\'\'}${num(raw)}`}</b><small>{raw==null?\'Unavailable\':raw>0?\'ABOVE VWAP\':raw<0?\'BELOW VWAP\':\'AT VWAP\'}</small></article>\n     <article><span>Lifecycle</span><b>{p?`${words(p.family)} · ${words(p.direction)}`:\'—\'}</b><small>{p?`Move ${num(p.directional_move)} · +20 ${yn(p.plus20)} · degraded ${yn(p.degraded)}`:\'No active position\'}</small></article>\n     <article><span>Option intent</span><b>{p?.option_intent??\'—\'}</b><small>{p?\'Exact basket attaches in M2.5B option observation.\':\'No active option intent\'}</small></article>\n   </div>\n   <div className="mp-next-transition"><span>WHAT MUST HAPPEN NEXT</span><p>{nextTransitionText(m)}</p></div>\n   {m.events?.length>0&&<div className="mp-explain-events"><span>IMMUTABLE EVENTS AT THIS MINUTE</span>{m.events.map(e=><b key={e.event_id}>{words(e.event_type)} · {semanticOwner(e)} · {words(e.result||e.reason)}</b>)}</div>}\n </div>\n}\n\n'
if "function MidpointFreshnessHeader" not in text:
    anchor="function EventCard({label,event}:{label:string;event:AuditEvent|null|undefined}){"
    if anchor not in text:
        raise SystemExit("STOP: EventCard anchor not found")
    text=text.replace(anchor,helper+anchor,1)

old_sig="function ReplayMinuteTable({minutes,onInspect,selected}:{minutes:ReplayMinute[];onInspect:(id:string)=>void;selected:AuditEvent|null}){return <section"
new_sig="function ReplayMinuteTable({minutes,onInspect,selected}:{minutes:ReplayMinute[];onInspect:(id:string)=>void;selected:AuditEvent|null}){const[explained,setExplained]=useState<string|null>(null);return <section"
if old_sig in text:
    text=text.replace(old_sig,new_sig,1)
elif "const[explained,setExplained]" not in text:
    raise SystemExit("STOP: ReplayMinuteTable signature not found")

old_events='{m.events?.length?<div className="mp-minute-events">{m.events.map(e=><div className="mp-minute-event" key={e.event_id}><div><b>{words(e.event_type)}</b><small>{semanticOwner(e)} · {words(e.direction)} · {words(e.result)}</small><small>{words(e.reason)}</small></div><button className="secondary" aria-expanded={selected?.event_id===e.event_id} onClick={()=>onInspect(e.event_id)}>{selected?.event_id===e.event_id?\'Collapse\':\'Inspect\'}</button></div>)}</div>:!m.presentation?<span className="mp-no-event">—</span>:null}</td></tr>,'
new_events='<div className="mp-minute-actions"><button className="secondary mp-explain-btn" aria-expanded={explained===m.timestamp} onClick={()=>setExplained(explained===m.timestamp?null:m.timestamp)}>{explained===m.timestamp?\'Close explanation\':\'Explain minute\'}</button></div>{m.events?.length?<div className="mp-minute-events">{m.events.map(e=><div className="mp-minute-event" key={e.event_id}><div><b>{words(e.event_type)}</b><small>{semanticOwner(e)} · {words(e.direction)} · {words(e.result)}</small><small>{words(e.reason)}</small></div><button className="secondary" aria-expanded={selected?.event_id===e.event_id} onClick={()=>onInspect(e.event_id)}>{selected?.event_id===e.event_id?\'Collapse\':\'Inspect\'}</button></div>)}</div>:!m.presentation?<span className="mp-no-event">—</span>:null}</td></tr>,explained===m.timestamp?<tr key={m.timestamp+\'-explain\'} className="mp-inline-detail-row"><td colSpan={9}><MinuteExplainPanel m={m}/></td></tr>:'
if old_events in text:
    text=text.replace(old_events,new_events,1)
elif "Explain minute" not in text:
    raise SystemExit("STOP: minute event block not found")

old_state=" const [loading,setLoading]=useState(true)"
new_state=" const [loading,setLoading]=useState(true)\n const [lastRefresh,setLastRefresh]=useState<string|null>(null)"
if old_state in text:
    text=text.replace(old_state,new_state,1)

for old,new in [
    ("setStatus(s);setTimeline(t.timeline);setMinutes([]);setError('')","setStatus(s);setTimeline(t.timeline);setMinutes([]);setLastRefresh(new Date().toISOString());setError('')"),
    ("setSelectedDate(date);setStatus(r.status);setTimeline(r.timeline);setMinutes(r.minutes??[]);setError('')","setSelectedDate(date);setStatus(r.status);setTimeline(r.timeline);setMinutes(r.minutes??[]);setLastRefresh(new Date().toISOString());setError('')"),
    ("setStatus(replay.status);setTimeline(replay.timeline);setMinutes(replay.minutes??[]);setError('')","setStatus(replay.status);setTimeline(replay.timeline);setMinutes(replay.minutes??[]);setLastRefresh(new Date().toISOString());setError('')")
]:
    if old in text:
        text=text.replace(old,new,1)

fresh_old="{mode==='HISTORICAL_REPLAY'&&selectedDate&&<div className=\"mp-replay-banner\""
fresh_new="<MidpointFreshnessHeader mode={mode} status={status} selectedDate={selectedDate} selectedSession={selectedSession} minutes={minutes} lastRefresh={lastRefresh}/>{mode==='HISTORICAL_REPLAY'&&selectedDate&&<div className=\"mp-replay-banner\""
if fresh_old in text:
    text=text.replace(fresh_old,fresh_new,1)
elif "<MidpointFreshnessHeader" not in text:
    raise SystemExit("STOP: freshness insertion point not found")

old_end="{loading&&!status?<section className=\"panel\"><div className=\"empty\">Loading Midpoint Strategy…</div></section>:<SessionView mode={mode} status={status} timeline={timeline} minutes={minutes} selected={selected} onInspect={id=>void inspect(id)}/>}</div>"
new_end="{loading&&!status?<section className=\"panel\"><div className=\"empty\">Loading Midpoint Strategy…</div></section>:<SessionView mode={mode} status={status} timeline={timeline} minutes={minutes} selected={selected} onInspect={id=>void inspect(id)}/>}<CheckpointComparison status={status}/></div>"
if old_end in text:
    text=text.replace(old_end,new_end,1)
elif "<CheckpointComparison status={status}/>" not in text:
    raise SystemExit("STOP: checkpoint insertion point not found")

tsx.write_text(text)
print("PATCHED:",tsx)

ct=css.read_text()
css_add='\n.mp-freshness{border:1px solid #2f5664;border-radius:8px;background:#0f2029;padding:12px 14px}.mp-freshness.stale{border-color:#8a6035}.mp-freshness-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}.mp-freshness-title>div{display:flex;align-items:baseline;gap:10px}.mp-freshness-title span{font-size:9px;color:#71c8bf;letter-spacing:.8px}.mp-freshness-title b{font-size:14px;color:#d8e6ec}.mp-freshness-title strong{font-size:9px;color:#d5bd77}.mp-freshness-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.mp-freshness-grid article{border:1px solid #253d48;background:#112630;border-radius:6px;padding:9px}.mp-freshness-grid span{display:block;font-size:8px;text-transform:uppercase;color:#758f9e;letter-spacing:.45px}.mp-freshness-grid b{display:block;margin:5px 0;font-size:10px;color:#d5e4eb}.mp-freshness-grid small{font-size:8px;color:#708995}.mp-stale-warning{margin-top:9px;padding:8px 10px;border:1px solid #7b5732;border-radius:5px;background:#2b2218;color:#deb66f;font-size:9px}.mp-checkpoint-table{min-width:1150px}.mp-checkpoint-table td:last-child{max-width:270px;white-space:normal}.mp-minute-actions{display:flex;justify-content:flex-end;margin-bottom:5px}.mp-explain-btn{font-size:8px!important;padding:4px 7px!important}.mp-minute-explain{padding:15px 18px;background:#0e1b23;box-shadow:inset 3px 0 0 #6c92d1}.mp-minute-explain-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:12px}.mp-minute-explain-head>div{display:flex;flex-direction:column;gap:3px}.mp-minute-explain-head span,.mp-next-transition span,.mp-explain-events span{font-size:8px;letter-spacing:.8px;color:#7ea4d8}.mp-minute-explain-head b{font-size:11px;color:#d8e5eb}.mp-minute-explain-head strong{font-size:10px;color:#7bd5af}.mp-minute-explain-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.mp-minute-explain-grid article{border:1px solid #29404b;background:#10232c;border-radius:6px;padding:10px}.mp-minute-explain-grid span{display:block;font-size:8px;color:#758e9b;text-transform:uppercase}.mp-minute-explain-grid b{display:block;margin:5px 0;font-size:12px;color:#d6e5ec}.mp-minute-explain-grid small{font-size:8px;color:#8298a5}.mp-next-transition{margin-top:10px;padding:10px 12px;border:1px solid #3c4f65;background:#111f2c;border-radius:6px}.mp-next-transition p{margin:5px 0 0;color:#c6d5dd;font-size:10px;line-height:1.45}.mp-explain-events{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:9px}.mp-explain-events b{font-size:8px;color:#b9cad3;border:1px solid #2c4350;border-radius:10px;padding:4px 7px}@media(max-width:1250px){.mp-freshness-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:900px){.mp-minute-explain-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.mp-freshness-grid,.mp-minute-explain-grid{grid-template-columns:1fr}.mp-freshness-title{align-items:flex-start;flex-direction:column}}\n'
if ".mp-freshness{" not in ct:
    css.write_text(ct+"\n"+css_add)
    print("PATCHED:",css)
else:
    print("M2.5A CSS already present")
